var n=`0713-koki`;var i=`world-0713`;var t=`CM`;var o=`central-africa`;var s=8;var l=577;var r={en:`Koki`,ua:`Кокі`};var d={en:`Koki is a Cameroon classic prepared with black-eyed peas, scotch bonnet pepper, yellow onion, banana leaf. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Кокі, страва кухні країни Камерун зі складниками: квасоля чорноочка, перець скотч-боннет, жовта цибуля, банановий лист. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var c=[{en:`Soak the dried beans or peas in plentiful cold water for 480 minutes, then drain and discard the soaking liquid; keep refrigerated in hot conditions.`,ua:`Замочіть сухі бобові у великій кількості холодної води на 480 хвилин, після чого злийте й вилийте воду від замочування; за спеки тримайте в холодильнику.`,t:[`soaking-legumes`],m:480,i:[[`black-eyed-peas`,410,`g`],[`water`,860,`ml`]]},{en:`Grind drained black-eyed peas into a smooth thick paste with palm oil, chili and onion; beat thoroughly to lighten.`,ua:`Збийте замочений обсушений чорноокий горох із пальмовою олією, чилі й цибулею в густу гладку пасту; ретельно вимішайте для пухкості.`,t:[`mixing`],m:16,i:[[`red-palm-oil`,90,`ml`],[`scotch-bonnet-pepper`,1,`pcs`],[`yellow-onion`,150,`g`],[`water`,180,`ml`],[`table-salt`,5,`g`]]},{en:`Spoon the paste into clean banana leaves and wrap into sealed parcels; place on a rack in the steamer.`,ua:`Розкладіть пасту на чисте бананове листя, загорніть у щільні згортки та покладіть на решітку пароварки.`,t:[`rolling-stuffed-food`],m:12,i:[[`banana-leaf`,4,`leaf`]]},{en:`Place leaf-wrapped portions in a steamer over gently boiling water and steam for about 65 minutes until fully cooked; use clean food-safe leaves.`,ua:`Покладіть порції в чистому харчовому листі у пароварку й готуйте над слабко киплячою водою близько 65 хвилин до повної готовності.`,t:[`banana-leaf-steaming`],m:65,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[]}];var p={slug:n,id:i,country:`CM`,region:o,servings:8,minutes:577,title:r,text:d,steps:c};export{t as country,p as default,i as id,l as minutes,o as region,s as servings,n as slug,c as steps,d as text,r as title};